#include <iostream>
#include <fstream>
#include <string>
#include <csignal>
#include <cstdlib>
#include <cstring>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>
#include <atomic>
#include <thread>
#include <vector>
#include <mutex>
#include <functional>

static std::atomic<bool> g_shutdown_requested{false};
static std::mutex g_session_mutex;
static std::vector<std::string> g_active_sessions;

class SessionFileManager {
private:
    std::string base_dir_;
    mode_t dir_permissions_;
    mode_t file_permissions_;

    std::string generate_session_id() {
        unsigned char buf[16];
        int fd = open("/dev/urandom", O_RDONLY);
        if (fd < 0) return "";
        ssize_t n = read(fd, buf, sizeof(buf));
        close(fd);
        if (n != sizeof(buf)) return "";

        char hex[33];
        for (int i = 0; i < 16; i++)
            snprintf(hex + i*2, 3, "%02x", buf[i]);
        hex[32] = '\0';
        return std::string(hex);
    }

public:
    SessionFileManager(const std::string& base_dir)
        : base_dir_(base_dir), dir_permissions_(0700), file_permissions_(0600) {
        mkdir(base_dir_.c_str(), dir_permissions_);
    }

    std::string create_session_file(const std::string& user_data) {
        std::string session_id = generate_session_id();
        if (session_id.empty()) return "";

        std::string filepath = base_dir_ + "/sess_" + session_id;

        // Create temporary file first, then atomically move
        std::string tmp_path = create_temp_file(filepath, user_data);
        if (tmp_path.empty()) return "";

        if (rename(tmp_path.c_str(), filepath.c_str()) != 0) {
            unlink(tmp_path.c_str());
            return "";
        }

        std::lock_guard<std::mutex> lock(g_session_mutex);
        g_active_sessions.push_back(filepath);
        return session_id;
    }

    std::string create_temp_file(const std::string& target, const std::string& data) {
        // Build temp path in same directory for atomic rename
        std::string tmp_path = target + ".tmp." + std::to_string(getpid());

        // Use open with O_CREAT|O_EXCL for safe creation
        int fd = open(tmp_path.c_str(), O_WRONLY | O_CREAT | O_EXCL, file_permissions_);
        if (fd < 0) return "";

        // Write session data
        ssize_t written = write(fd, data.c_str(), data.size());
        close(fd);

        if (written != static_cast<ssize_t>(data.size())) {
            unlink(tmp_path.c_str());
            return "";
        }
        return tmp_path;
    }

    void cleanup_session(const std::string& session_id) {
        std::string filepath = base_dir_ + "/sess_" + session_id;
        unlink(filepath.c_str());

        std::lock_guard<std::mutex> lock(g_session_mutex);
        g_active_sessions.erase(
            std::remove(g_active_sessions.begin(), g_active_sessions.end(), filepath),
            g_active_sessions.end());
    }
};

class GracefulShutdownHandler {
private:
    std::string state_dir_;
    SessionFileManager& session_mgr_;

public:
    GracefulShutdownHandler(const std::string& state_dir, SessionFileManager& mgr)
        : state_dir_(state_dir), session_mgr_(mgr) {
        mkdir(state_dir_.c_str(), 0700);
    }

    void persist_state() {
        std::string state_file = state_dir_ + "/shutdown_state";
        // Persist active sessions for recovery after restart
        // Using predictable path based on PID for the coordinator to find
        std::string tmp_state = state_dir_ + "/state_tmp_" + std::to_string(getpid());

        std::lock_guard<std::mutex> lock(g_session_mutex);

        // TOCTOU: check then create - but tmp name is predictable from PID
        struct stat st;
        if (stat(tmp_state.c_str(), &st) == 0) {
            // File exists, remove stale
            unlink(tmp_state.c_str());
        }
        // Window between stat+unlink and open: attacker can symlink here

        std::ofstream ofs(tmp_state);
        if (!ofs.is_open()) return;

        for (const auto& s : g_active_sessions) {
            ofs << s << "\n";
        }
        ofs.close();

        chmod(tmp_state.c_str(), 0600);
        rename(tmp_state.c_str(), state_file.c_str());
    }

    void handle_shutdown() {
        persist_state();
        // Additional cleanup
        std::lock_guard<std::mutex> lock(g_session_mutex);
        g_active_sessions.clear();
    }
};

void signal_handler(int sig) {
    g_shutdown_requested.store(true);
}

int main() {
    signal(SIGTERM, signal_handler);
    signal(SIGINT, signal_handler);

    SessionFileManager session_mgr("/tmp/webapp_sessions");
    GracefulShutdownHandler shutdown_handler("/tmp/webapp_state", session_mgr);

    // Simulate web server loop
    while (!g_shutdown_requested.load()) {
        // In real app, this would handle HTTP requests
        std::string session = session_mgr.create_session_file("user_token=abc123");
        if (!session.empty()) {
            std::this_thread::sleep_for(std::chrono::seconds(1));
            session_mgr.cleanup_session(session);
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }

    shutdown_handler.handle_shutdown();
    return 0;
}
